namespace v2rayN.Desktop.Common;

/// <summary>
/// One icon style for the whole app. Semi ships a mix of filled and outlined glyphs, and many
/// outlined ones have no counterpart, so V2pn draws its icons from Lucide instead
/// (LucideIcons.g.cs, generated by tools/icons/gen_lucide.py).
/// Lucide icons are strokes; PathIcon fills. Each outline is widened here, once at start, into the
/// shape its 2-px stroke would paint, and registered under the Semi name the views already use. So
/// every PathIcon, menu item and Semi control keeps working unchanged and simply shows the Lucide
/// glyph, on the same 24x24 grid so all icons keep the same visual size.
/// </summary>
internal static partial class Icons
{
    private const double Stroke = 2;

    /// <summary>Registers the icons as app resources; they outrank the Semi theme's own.</summary>
    public static void Install(Application app)
    {
        var pen = new Pen(Brushes.Black, Stroke, lineCap: PenLineCap.Round, lineJoin: PenLineJoin.Round);
        // Zero-area points at the grid corners keep the 24x24 frame in the bounds that PathIcon
        // scales by; otherwise a small glyph such as "x" would grow to fill the whole box.
        var frame = Geometry.Parse("M0,0 Z M24,24 Z");
        foreach (var (key, data) in Lucide)
        {
            try
            {
                var outline = Geometry.Parse(data);
                var group = new GeometryGroup { FillRule = FillRule.NonZero };
                if (outline.GetWidenedGeometry(pen) is { } widened)
                {
                    group.Children.Add(widened);
                }
                if (Filled.Contains(key))
                {
                    group.Children.Add(outline);
                }
                group.Children.Add(frame);
                app.Resources[key] = group;
            }
            catch (Exception ex)
            {
                // A glyph that fails to parse keeps the Semi original.
                Logging.SaveLog($"Icons {key}", ex);
            }
        }
    }
}
